const h = $input.first().json.headers || {};
let sc = h['set-cookie'];
if (!sc) throw new Error('O login do dash não devolveu cookie.');
const arr = Array.isArray(sc) ? sc : [sc];
return [{ json: { cookie: arr.map(c => c.split(';')[0]).join('; ') } }];

const b = ($('Webhook dados').first().json.body) || {};
const cfg = $('Config').first().json;
const cookie = $('Cookie do dash').first().json.cookie;
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const p2 = n => String(n).padStart(2, '0');
const erro = (message, extra) => [{ json: { ok: false, erro: message, ...(extra || {}) } }];

// ---------- cliente ----------
let dash = $('Dash - lista de clientes').all().map(i => i.json);
if (dash.length === 1 && Array.isArray(dash[0].clients)) dash = dash[0].clients;
dash = dash.filter(c => c && c.id && c.name);
const q = norm(b.cliente);
if (!q) return erro('Informe o cliente.', { clientes: dash.map(c => c.name) });
let hits = dash.filter(c => norm(c.name) === q || c.slug === String(b.cliente).trim());
if (!hits.length) hits = dash.filter(c => norm(c.name).startsWith(q));
if (!hits.length && q.length >= 3) hits = dash.filter(c => norm(c.name).includes(q));
if (hits.length !== 1) return erro(hits.length ? 'Mais de um cliente com esse nome: ' + hits.map(h => h.name).join(', ') : 'Cliente não encontrado no dash.', { clientes: dash.map(c => c.name) });
const cli = hits[0];

// ---------- períodos ----------
const hoje = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo' }).format(new Date());
const [Y, M, D] = hoje.split('-').map(Number);
const iso = (y, m, d) => y + '-' + p2(m) + '-' + p2(d);
const lastDay = (y, m) => new Date(Date.UTC(y, m, 0)).getUTCDate();
const addDays = (s, n) => { const [y, m, d] = s.split('-').map(Number); const t = new Date(Date.UTC(y, m - 1, d + n)); return iso(t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate()); };
const diffDays = (a, c) => Math.round((Date.UTC(...c.split('-').map((x, i) => i === 1 ? x - 1 : +x)) - Date.UTC(...a.split('-').map((x, i) => i === 1 ? x - 1 : +x))) / 86400000);
let from, to, prevFrom, prevTo, mes;
const re = /^\d{4}-\d{2}-\d{2}$/;
if (b.from && b.to) {
  if (!re.test(b.from) || !re.test(b.to)) return erro('from/to devem ser AAAA-MM-DD.');
  from = b.from; to = b.to; mes = from.slice(0, 7);
  const n = diffDays(from, to) + 1;
  prevTo = b.prev_to || addDays(from, -1); prevFrom = b.prev_from || addDays(prevTo, -(n - 1));
} else {
  mes = b.mes || (Y + '-' + p2(M));
  if (!/^\d{4}-\d{2}$/.test(mes)) return erro('mes deve ser AAAA-MM.');
  const [y, m] = mes.split('-').map(Number);
  from = iso(y, m, 1); to = (y === Y && m === M) ? hoje : iso(y, m, lastDay(y, m));
  const py = m === 1 ? y - 1 : y, pm = m === 1 ? 12 : m - 1;
  prevFrom = iso(py, pm, 1); prevTo = iso(py, pm, lastDay(py, pm));
}
if (to > hoje) return erro('O período termina no futuro.');
const parcial = to >= hoje;

// ---------- coleta ----------
const avisos = [];
const base = cfg.dashBase + '/api/clients/' + cli.id;
const get = async (path, nome) => {
  try { return await this.helpers.httpRequest({ method: 'GET', url: base + path, headers: { Cookie: cookie }, json: true, timeout: 30000 }); }
  catch (e) { avisos.push('Falha ao ler ' + nome + ' do dash: ' + (e.message || e)); return null; }
};
const [rep, repPrev, ads, leads, site, docEst, docFca] = await Promise.all([
  get('/report?from=' + from + '&to=' + to, 'relatório'),
  get('/report?from=' + prevFrom + '&to=' + prevTo, 'relatório do período anterior'),
  get('/ads?from=' + from + '&to=' + to, 'anúncios'),
  get('/leads?from=' + from + '&to=' + to, 'leads'),
  get('/site?from=' + from + '&to=' + to, 'site/GA4/Clarity'),
  get('/docs?kind=estrategia', 'estratégia'),
  get('/docs?kind=relatorio_fca', 'relatórios FCA'),
]);
if (!rep || !rep.client) return erro('O dash não devolveu o relatório deste cliente.', { avisos });

// ---------- KPIs ----------
const div = (a, c) => (c ? a / c : null);
const rd = n => (n == null || !Number.isFinite(n) ? null : Math.round((n + Number.EPSILON) * 100) / 100);
function kpis(r) {
  if (!r || !r.client) return null;
  const ecom = r.client.businessType === 'ecommerce' || (r.hybrid === true && (r.store || (r.ecom && r.ecom.revenue > 0)));
  const plats = r.platforms || {};
  const porPlataforma = {};
  let invest = 0, vendas, fat;
  if (ecom) {
    (r.campaigns || []).filter(c => c.segment === 'ecommerce' && c.stage !== 'reconhecimento').forEach(c => { porPlataforma[c.platform] = (porPlataforma[c.platform] || 0) + (c.spend || 0); });
    const st = r.store, ec = r.ecom || {};
    vendas = st ? (st.orders || 0) : Math.round(ec.purchases || 0); fat = st ? (st.revenue || 0) : (ec.revenue || 0);
  } else {
    Object.entries(plats).forEach(([k, p]) => { porPlataforma[k] = p.spendPerformance || 0; });
    vendas = (r.funnel || {}).sales || 0; fat = (r.funnel || {}).revenue || 0;
  }
  invest = Object.values(porPlataforma).reduce((a, v) => a + v, 0);
  const f = r.funnel || {};
  const imp = Object.values(plats).reduce((a, p) => a + (p.impressions || 0), 0);
  const cli_ = Object.values(plats).reduce((a, p) => a + (p.clicks || 0), 0);
  const gasto = Object.values(plats).reduce((a, p) => a + (p.spend || 0), 0);
  const g = r.ga4 || {};
  return {
    modelo: ecom ? 'ecommerce' : 'inside_sales',
    investimento_performance: rd(invest), investimento_total: rd(gasto),
    investimento_por_plataforma: Object.fromEntries(Object.entries(porPlataforma).map(([k, v]) => [k, rd(v)])),
    faturamento: rd(fat), vendas, ticket_medio: rd(div(fat, vendas)), roas: rd(div(fat, invest)),
    impressoes: imp, cliques: cli_, ctr_pct: rd(div(cli_, imp) * 100), cpc: rd(div(gasto, cli_)), cpm: rd(div(gasto, imp) * 1000),
    leads: f.leads || 0, mql: f.mql || 0, sql: f.sql || 0,
    cpl: rd(div(invest, f.leads)), custo_mql: rd(div(invest, f.mql)), custo_sql: rd(div(invest, f.sql)), custo_venda: rd(div(invest, vendas)),
    tx_lead_mql_pct: rd(div(f.mql, f.leads) * 100), tx_mql_sql_pct: rd(div(f.sql, f.mql) * 100), tx_sql_venda_pct: rd(div(vendas, f.sql) * 100),
    sessoes_ga4: g.sessions || 0, add_to_cart: g.addToCart || 0,
  };
}
const k = kpis(rep), kp = kpis(repPrev);
const delta = (a, c) => (a == null || c == null || c === 0 ? null : rd((a - c) / c * 100));
const variacao = k && kp ? Object.fromEntries(['investimento_performance', 'faturamento', 'vendas', 'roas', 'leads', 'mql', 'sql', 'cpl', 'ticket_medio'].map(x => [x, delta(k[x], kp[x])])) : null;

// ---------- meta da Central ----------
const fv = v => { if (v == null) return null; if ('doubleValue' in v) return v.doubleValue; if ('integerValue' in v) return Number(v.integerValue); if ('stringValue' in v) return v.stringValue; if ('nullValue' in v) return null; if ('mapValue' in v) return Object.fromEntries(Object.entries(v.mapValue.fields || {}).map(([a, c]) => [a, fv(c)])); return null; };
const alias = JSON.parse(cfg.aliases || '{}');
const docs = ($('Central - ler metas').first().json.documents) || [];
let meta = null;
for (const d of docs) {
  const f = d.fields || {}; const nm = norm(fv(f.cliente)); const alvo = alias[nm] || nm; const nd = norm(cli.name);
  if (String(fv(f.mes) || '') === mes && (alvo === nd || (nd.length >= 4 && alvo.startsWith(nd)) || (alvo.length >= 4 && nd.startsWith(alvo)))) {
    meta = { cliente_central: fv(f.cliente), mes, modelo: fv(f.modelo), provavel: fv(f.provavel), otimista: fv(f.otimista), pessimista: fv(f.pessimista), realizado: fv(f.realizado) };
    break;
  }
}
if (meta && meta.realizado && meta.realizado.faturamento && k && k.faturamento && Math.abs(meta.realizado.faturamento - k.faturamento) / k.faturamento > 0.1) avisos.push('Faturamento divergente: o dash mostra ' + k.faturamento + ' e o "realizado" da Central tem ' + meta.realizado.faturamento + '. Concilie as fontes antes de apresentar ao cliente.');
if (!meta) avisos.push('Sem meta cadastrada na Central para ' + mes + '. Não é possível mostrar atingimento da meta.');

// ---------- blocos resumidos ----------
const adsLista = ((ads && ads.ads) || []).map(a => ({
  nome: a.name, plataforma: a.platform, status: a.status, campanha: a.campaign_name, conjunto: a.adset_name,
  formato: a.creative && a.creative.format, titulo: a.creative && a.creative.title, texto: a.creative && a.creative.body ? String(a.creative.body).slice(0, 280) : null,
  miniatura: a.creative && a.creative.thumbnail_url, previa: a.creative && a.creative.preview_url,
  gasto: rd(a.metrics && a.metrics.spend), impressoes: a.metrics && a.metrics.impressions, cliques: a.metrics && a.metrics.link_clicks,
  ctr_pct: rd(a.metrics && a.metrics.ctr), cpc: rd(a.metrics && a.metrics.cpc), resultados: a.metrics && a.metrics.results, custo_por_resultado: rd(a.metrics && a.metrics.cost_per_result),
})).sort((x, y) => (y.gasto || 0) - (x.gasto || 0));
const campanhas = (rep.campaigns || []).map(c => ({ plataforma: c.platform, nome: c.name, etapa: c.stage, segmento: c.segment, status: c.status, objetivo: c.objective,
  gasto: rd(c.spend), impressoes: c.impressions, cliques: c.clicks, leads_rastreados: c.trackedLeads, conversas: c.conversations, compras: c.purchases, valor_conversao: rd(c.conversionValue),
  ctr_pct: rd(div(c.clicks, c.impressions) * 100), cpc: rd(div(c.spend, c.clicks)), custo_por_lead: rd(div(c.spend, c.trackedLeads)) })).sort((x, y) => (y.gasto || 0) - (x.gasto || 0));
const L = (leads && leads.leads) || [];
const porCanal = {};
L.forEach(l => { const c = l.channel || 'nao_informado'; const o = porCanal[c] = porCanal[c] || { leads: 0, mql: 0, sql: 0, vendas: 0, faturamento: 0 }; o.leads++; if (l.is_mql) o.mql++; if (l.is_sql) o.sql++; if (l.is_sale) { o.vendas++; o.faturamento += l.sale_value || 0; } });
const porOrigem = {};
L.forEach(l => { const s = l.source_detail || 'não informado'; porOrigem[s] = (porOrigem[s] || 0) + 1; });
const funilLeads = { total: L.length, por_canal: porCanal, origens_top: Object.entries(porOrigem).sort((x, y) => y[1] - x[1]).slice(0, 8).map(([origem, qtd]) => ({ origem, qtd })) };
const clar = (site && site.clarity) || {};
const dias = clar.days || [];
const siteRes = site ? {
  origens: (site.sources || []).slice(0, 10), paginas: (site.pages || []).slice(0, 10),
  clarity: { configurado: !!clar.configured, sessoes: dias.reduce((a, d) => a + (d.sessions || 0), 0), dias_com_retrato: dias.length },
} : null;
const fcaData = (docFca && docFca.data) || null;
let fcaUltimo = null;
if (fcaData) { const ks = Object.keys(fcaData).sort(); const kk = ks[ks.length - 1]; fcaUltimo = kk ? { periodo: kk, ...fcaData[kk] } : null; }

// ---------- avisos de qualidade ----------
if (k && k.leads === 0 && k.modelo === 'inside_sales') avisos.push('Funil zerado no dash (sem leads na planilha neste período): não use taxas de funil.');
if (rep.hasSheet === false && k && k.modelo === 'inside_sales') avisos.push('Cliente sem planilha de leads vinculada.');
if (!adsLista.length) avisos.push('Nenhum anúncio com impressão no período: slide de criativos deve ficar de fora ou ser marcado como sem dado.');
if (siteRes && !siteRes.origens.length && !(rep.ga4 && rep.ga4.sessions)) avisos.push('GA4 não vinculado ou sem dados: não há dados de site/sessões.');
if (siteRes && siteRes.clarity.sessoes === 0) avisos.push('Clarity sem sessões no período.');
if (rep.lastSync && (Date.now() - new Date(rep.lastSync).getTime()) > 36 * 3600 * 1000) avisos.push('Última sincronização do dash tem mais de 36 horas: números podem estar defasados.');
if (parcial) avisos.push('Período parcial (até ' + to + '): rotule como "resultado parcial".');
if (k && kp && kp.investimento_performance === 0 && kp.leads === 0 && kp.vendas === 0) avisos.push('Período anterior sem dados: comparação mês a mês indisponível.');
avisos.push('Redes sociais/orgânico: o dash não fornece esse bloco; preencha manualmente ou omita o slide.');

return [{ json: {
  ok: true,
  cliente: { nome: cli.name, slug: cli.slug, tipo: cli.businessType, verba_mensal: cli.monthlyBudget, ticket_referencia: cli.ticket },
  periodo: { de: from, ate: to, parcial, mes }, periodo_anterior: { de: prevFrom, ate: prevTo },
  ultima_sincronizacao: rep.lastSync || null,
  kpis: k, kpis_anterior: kp, variacao_pct: variacao,
  meta_central: meta, metas_dash: rep.goals || [],
  canais_funil: rep.byChannel || null, plataformas: rep.platforms || null,
  campanhas, anuncios: adsLista, leads_resumo: funilLeads,
  serie_diaria: (rep.daily || []).map(d => ({ data: d.date, gasto: rd(d.spend), leads: d.leads, mql: d.mql, sql: d.sql, vendas: d.sales, faturamento: rd(d.revenue), sessoes: d.sessions })),
  site: siteRes, ultimo_relatorio_fca: fcaUltimo, estrategia: docEst && docEst.data ? docEst.data : null,
  avisos,
} }];
